import json,re
from pathlib import Path
R=Path(__file__).parent
slides=json.loads((R/'screen-ar.json').read_text())
notes={}
for f in sorted(R.glob('notes-*.json')): notes.update(json.loads(f.read_text()))
old={}
for f in (R.parent/'dauroh-v4-fluent').glob('notes-*.json'):old.update(json.loads(f.read_text()))
mapping={42:22,63:24,66:34,68:26,69:31,70:30,85:37,86:38,90:42,94:44,100:47,105:48}
for new,prev in mapping.items():notes[str(new)]=old[str(prev)]['script']
notes['63']=notes['63'].replace('تعاملنا حتى الآن مع مادة مشتركة، فأصبح من السهل مقارنة خطواتنا. ننتقل إلى موضوع تعرفون شيئًا من مادته.','بعد التعرّف على طرق جمع المصادر، نختار موضوعًا نعرف شيئًا من مادته.').replace('الحالة التدريبية المتاحة','مسألة من كتاب يدرسه')
notes['66']=notes['66'].replace('تمييز النقل والتلخيص في النص التدريبي','استعمال مصطلح في كتابين').replace('دراسة التوثيق كله','دراسة المصطلح في التراث كله').replace('وبعد ضبط السؤال والأهداف، ننظر إلى العنوان الذي سيحمل هذا العمل دون أن يعد بما لا ينجزه.','ثم نراجع الأهداف والفائدة وحدود هذا العمل. ونميز الإشكالية من مجرد اسم الموضوع. الإشكالية تشرح ما الذي يستدعي الدراسة، مثل اختلاف استعمال المصطلح أو غموض العلاقة بين نصين. نحتاج إلى قرائن على وجود هذه المسألة قبل أن نصفها بأنها مشكلة بحثية.')
notes['68']=notes['68'].replace('احفظوا البطاقة الآن؛ فهي التي سنبني عليها العمل في اليوم الثاني، ومعها واجب خفيف من المصدر الذي بدأنا به.','أمامكم عشر دقائق. اكتبوا السؤال والهدف والحدود، وسجلوا أمرًا واحدًا تريدون مناقشته مع المشرف. احفظوا البطاقة الآن، فسنستخدمها في مراجعة الكلمات المفتاحية والدراسات السابقة، ثم في الخطة والكتابة.')
notes['69']=notes['69'].replace('سنرى مسارًا جُرّب قبل الدورة، ثم يطبّق كل واحد على سؤاله أو على الحزمة.','نطبق ذلك على سؤالكم ومصدر متاح، ونحفظ ما نستطيع فحصه.').replace('وإذا تعطل الموقع، نستعمل النسخة المحفوظة','وإذا تعطل الموقع، نبحث عن نسخة متاحة')
notes['70']=notes['70'].replace('والسؤال العملي التالي هو: كيف نحول ألفاظ المسألة إلى طريق يصل بنا إلى نص مفتوح؟','بعد تحديد وظيفة المصدر، نتحقق من وجوده وبياناته وموضع العبارة التي سنستخدمها. أما ملخص الأداة فنحفظه بوصفه مساعدة على القراءة، ونراجع نسبته إلى النص الذي يلخصه.')
notes['86']=notes['86'].replace('والآن سنجرّب ذلك في خططكم أنتم.','أمامكم عشر دقائق لتجربة ذلك في خططكم أنتم. اكتبوا خطة مختصرة، وحددوا جزءًا يخدم السؤال، وموضع تكرار إن وجد، ومادة ما زلتم تحتاجون إليها. ثم يشرح أحدكم سبب تعديل واحد، حتى نفهم أثر المراجعة في ترتيب البحث.')
notes['90']=notes['90'].replace('فقرة الواجب','فقرة سبق أن كتبتموها')
notes['94']=notes['94'].replace('بعد مراجعة المعنى والدليل، ننتقل إلى طبقة أخرى، هي الصياغة اللغوية.','بعد مراجعة المعنى والدليل، نستطيع ضبط النتائج بما أنجزناه فعلًا.')
notes['100']+='\n\nسنمر على الذكاء الاصطناعي، والمكتبة، والمخطوطات، والدورات. وفي كل مشروع نحدد الحاجة التي يخدمها، ونميز غايته عما أصبح متاحًا في النسخة المعروضة. ثم نختار تطبيقًا قصيرًا يمكننا متابعته معًا.'
notes['105']=notes['105'].replace('بقي أن نجرب مقدار ما أصبح كل واحد منا يستطيع عمله بنفسه.','نخصص نحو خمس دقائق لهذا المثال ضمن الجولة. نختم بتحديد ما أفادنا وما بقي للباحث، ثم نضع خطوة متابعة بعد الدورة.')
for d in slides:
 n=notes[str(d['id'])]
 if isinstance(n,dict): n=n['script']
 d['notes']=n.replace('Google','جوجل')
 assert len(d['notes'].split())>=100,(d['id'],len(d['notes'].split()))
 assert 'خلدون' not in str(d)
(R/'slides.json').write_text(json.dumps(slides,ensure_ascii=False,indent=2)+'\n')
text=['# الذكاء الاصطناعي للتعلّم والبحث\n']
for d in slides:
 text.append(f"\n## الشريحة {d['id']}: {d['title']}\n\nاليوم {d['day']}، {d['chapter']}\n")
 for b in d['body']:text.append('- '+('، '.join(b) if isinstance(b,list) else b))
 text.append('\n### نص الإلقاء\n\n'+d['notes']+'\n')
 if d.get('refs'):text.append('\nالمراجع:\n'+'\n'.join(d['refs']))
(R/'النص_الكامل.md').write_text('\n'.join(text)+'\n')
print({'slides':len(slides),'notes_words':sum(len(d['notes'].split()) for d in slides),'minimum_note_words':min(len(d['notes'].split()) for d in slides)})
